  if (lines[i].startsWith('function processRule(')) { start = i; break; }
}
console.log('processRule starts at line', start + 1);
let depth = 0;
let end = -1;
for (let i = start; i < lines.length; i++) {
  for (const ch of lines[i]) {
    if (ch === '{') depth++;
    else if (ch === '}') depth--;
  }
  if (depth === 0 && i > start) { end = i; break; }
}
console.log('processRule ends at line', end + 1);
