+    return { number: 1437, title: 'feat: t', labels: [],
+      head: { ref: 'ai/1437', sha: sha || HEAD }, user: { login: 'bot' },
+      created_at: '2026-10-09T10:00:00Z' };
+  }
+  function mergedPr(sha) {
+    return { number: 1437, title: 'feat: t', labels: [],
+      head: { ref: 'ai/1437', sha: sha || HEAD }, user: { login: 'bot' },
+      created_at: '2026-10-09T10:00:00Z', merged_at: '2026-10-09T11:57:03Z' };
+  }
