const fs = require('fs');
const src = fs.readFileSync('js/smAgent.js', 'utf8');
const lines = src.split('\n');
// find 'function processRule' start line and count braces to find its end
let start = -1;
for (let i = 0; i < lines.length; i++) {
  if (lines[i].startsWith('function processRule(')) { start = i; break; }
}
console.log('processRule starts at line', start + 1);
let depth = 0;
let end = -1;
for (let i = start; i < lines.length; i++) {
  for (const ch of lines[i]) {
    if (ch === '{') depth++;
    else if (ch === '}') depth--;
  }
  if (depth === 0 && i > start) { end = i; break; }
}
console.log('processRule ends at line', end + 1);
// Now find state publish block lines
const spStart = lines.findIndex(l => l.includes('Factory state publishing'));
console.log('state publish comment at line', spStart + 1, 'depth at that point:');
// compute depth before it
let d2 = 0;
for (let i = start; i < spStart; i++) {
  for (const ch of lines[i]) {
    if (ch === '{') d2++;
    else if (ch === '}') d2--;
  }
}
console.log('brace depth at statePublish line relative to processRule start:', d2);
