function buildFactoryState(input) {
    var prs = input.prs || [];
    var mergedPrs = input.mergedPrs || [];
    var issues = input.issues || input.devIssues || [];
    var runs = input.runs || [];
    var checkNames = input.checkNames || [];
    var now = input.now || new Date().toISOString();
    var nowMs = Date.parse(now);
